from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

import event_store
from signature_utils import verify_signature

SIGNATURE_HEADER = "X-Webhook-Signature"


def _reject(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate one payment event and enqueue it."""

    secret = os.environ.get("WEBHOOK_SECRET")
    if not secret:
        return _reject("missing secret configuration")

    headers = request.get("headers") if isinstance(request, Mapping) else None
    body = request.get("body") if isinstance(request, Mapping) else None
    if not isinstance(headers, Mapping) or not isinstance(body, bytes):
        return _reject("malformed request")

    signature = headers.get(SIGNATURE_HEADER)
    if not verify_signature(body, signature, secret):
        return _reject("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _reject("invalid JSON body")

    if not isinstance(event, Mapping):
        return _reject("malformed event")

    for field in ("event_id", "event_type", "account_id"):
        if not isinstance(event.get(field), str) or not event[field]:
            return _reject("missing field: ...")

    event_store.append_event(dict(event))  # or event
    return {"status": "accepted", "event_id": event["event_id"]}
```

