"""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature

SIGNATURE_HEADER = "X-Webhook-Signature"
REQUIRED_FIELDS = ("event_id", "event_type", "account_id")


def _rejected(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def _signature_header(headers: Mapping[str, Any]) -> object:
    if SIGNATURE_HEADER in headers:
        return headers[SIGNATURE_HEADER]
    lowered = SIGNATURE_HEADER.lower()
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == lowered:
            return value
    return None


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate one payment event and enqueue it."""

    secret = os.environ.get("WEBHOOK_SECRET")
    if not secret:
        return _rejected("receiver secret not configured")

    if not isinstance(request, Mapping):
        return _rejected("malformed request")

    headers = request.get("headers")
    body = request.get("body")
    if not isinstance(headers, Mapping) or not isinstance(body, bytes):
        return _rejected("malformed request")

    signature = _signature_header(headers)
    if signature is None:
        return _rejected("missing signature")
    if not verify_signature(body, signature, secret):
        return _rejected("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return _rejected("invalid JSON body")

    if not isinstance(event, dict):
        return _rejected("malformed event")

    for field in REQUIRED_FIELDS:
        if not isinstance(event.get(field), str):
            return _rejected(f"malformed event: {field} must be a string")

    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
```

